#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n;
        long long k, l;
        cin >> n >> k >> l;

        vector<long long> a(n);
        for (long long &x : a) cin >> x;

        long long tide = k;
        bool rising = false;
        bool possible = true;

        for (long long depth : a) {
            if (depth > l) {
                possible = false;
                continue;
            }

            if (depth + k <= l) {
                tide = k;
                rising = false;
            } else if (rising) {
                ++tide;
                if (depth + tide > l) possible = false;
            } else {
                tide = min(tide - 1, l - depth);
                if (tide < 0) {
                    possible = false;
                } else if (tide == 0) {
                    rising = true;
                }
            }
        }

        cout << (possible ? "Yes" : "No") << '\n';
    }

    return 0;
}

